package android.graphics;
public class Matrix {
 public static final int MSCALE_X=0,MSKEW_X=1,MTRANS_X=2,MSKEW_Y=3,MSCALE_Y=4,MTRANS_Y=5,MPERSP_0=6,MPERSP_1=7,MPERSP_2=8;
 private float[] v=new float[9]; public Matrix(){reset();} public Matrix(Matrix m){set(m);} public void reset(){for(int i=0;i<9;i++)v[i]=0;v[0]=v[4]=v[8]=1;} public void set(Matrix m){if(m==null)reset();else m.getValues(v);} public void getValues(float[] a){for(int i=0;i<9;i++)a[i]=v[i];} public void setValues(float[] a){for(int i=0;i<9;i++)v[i]=a[i];} public boolean isIdentity(){return equals(new Matrix());} public boolean equals(Object o){if(!(o instanceof Matrix))return false;float[] a=((Matrix)o).v;for(int i=0;i<9;i++)if(v[i]!=a[i])return false;return true;} public int hashCode(){return 1;}
 private static float[] mul(float[] a,float[] b){float[] c=new float[9];for(int i=0;i<3;i++)for(int j=0;j<3;j++)for(int k=0;k<3;k++)c[i*3+j]+=a[i*3+k]*b[k*3+j];return c;} public boolean setConcat(Matrix a,Matrix b){v=mul(a.v,b.v);return true;} public boolean preConcat(Matrix m){v=mul(v,m.v);return true;} public boolean postConcat(Matrix m){v=mul(m.v,v);return true;}
 public void setTranslate(float x,float y){reset();v[2]=x;v[5]=y;} public void setScale(float x,float y){reset();v[0]=x;v[4]=y;} public void setScale(float x,float y,float px,float py){setScale(x,y);v[2]=px-x*px;v[5]=py-y*py;} public void setSkew(float x,float y){reset();v[1]=x;v[3]=y;} public void setSkew(float x,float y,float px,float py){setSkew(x,y);v[2]=-x*py;v[5]=-y*px;} public void setRotate(float d){reset();double r=d*Math.PI/180;v[0]=v[4]=(float)Math.cos(r);v[1]=-(v[3]=(float)Math.sin(r));} public void setRotate(float d,float x,float y){setRotate(d);v[2]=x-v[0]*x-v[1]*y;v[5]=y-v[3]*x-v[4]*y;}
 public boolean preTranslate(float x,float y){Matrix m=new Matrix();m.setTranslate(x,y);return preConcat(m);} public boolean postTranslate(float x,float y){Matrix m=new Matrix();m.setTranslate(x,y);return postConcat(m);} public boolean preScale(float x,float y){return preScale(x,y,0,0);} public boolean preScale(float x,float y,float px,float py){Matrix m=new Matrix();m.setScale(x,y,px,py);return preConcat(m);} public boolean postScale(float x,float y){return postScale(x,y,0,0);} public boolean postScale(float x,float y,float px,float py){Matrix m=new Matrix();m.setScale(x,y,px,py);return postConcat(m);} public boolean preRotate(float d){return preRotate(d,0,0);} public boolean preRotate(float d,float x,float y){Matrix m=new Matrix();m.setRotate(d,x,y);return preConcat(m);} public boolean postRotate(float d){return postRotate(d,0,0);} public boolean postRotate(float d,float x,float y){Matrix m=new Matrix();m.setRotate(d,x,y);return postConcat(m);} public boolean preSkew(float x,float y){Matrix m=new Matrix();m.setSkew(x,y);return preConcat(m);} public boolean postSkew(float x,float y){Matrix m=new Matrix();m.setSkew(x,y);return postConcat(m);}
 public boolean invert(Matrix out){float a=v[0],b=v[1],c=v[2],d=v[3],e=v[4],f=v[5],det=a*e-b*d;if(det==0)return false;float[] n={e/det,-b/det,(b*f-e*c)/det,-d/det,a/det,(d*c-a*f)/det,0,0,1};out.setValues(n);return true;}
 public void mapPoints(float[] pts){mapPoints(pts,0,pts,0,pts.length/2);} public void mapPoints(float[] dst,float[] src){mapPoints(dst,0,src,0,src.length/2);} public void mapPoints(float[] dst,int di,float[] src,int si,int count){float[] tmp=new float[count*2];for(int i=0;i<count;i++){float x=src[si+2*i],y=src[si+2*i+1],w=v[6]*x+v[7]*y+v[8];tmp[2*i]=(v[0]*x+v[1]*y+v[2])/w;tmp[2*i+1]=(v[3]*x+v[4]*y+v[5])/w;}for(int i=0;i<tmp.length;i++)dst[di+i]=tmp[i];} public boolean mapRect(RectF r){return mapRect(r,r);} public boolean mapRect(RectF dst,RectF src){float[] a={src.left,src.top,src.right,src.top,src.right,src.bottom,src.left,src.bottom};mapPoints(a);float l=a[0],r=l,t=a[1],b=t;for(int i=2;i<8;i+=2){l=Math.min(l,a[i]);r=Math.max(r,a[i]);t=Math.min(t,a[i+1]);b=Math.max(b,a[i+1]);}dst.set(l,t,r,b);return v[1]==0&&v[3]==0;} public float mapRadius(float r){return r*(float)Math.sqrt(Math.sqrt((v[0]*v[0]+v[3]*v[3])*(v[1]*v[1]+v[4]*v[4])));}
 public void mapVectors(float[] a){for(int i=0;i+1<a.length;i+=2){float x=a[i],y=a[i+1];a[i]=v[0]*x+v[1]*y;a[i+1]=v[3]*x+v[4]*y;}} }